    31	bool Cat::Initialize() {
    32	  opt_desc_.add_options()("help,h", "Concatenate FILE to standard output.")(
    33	      "path", po::value<std::string>(),
    34	      "The path to the file that needs to be cat-ed");
    35	
    36	  // We allow only one argument to be passed to this tool. An exception is
    37	  // thrown if multiple arguments are passed.
    38	  pos_opt_desc_.add("path", 1);
    39	
    40	  po::store(po::command_line_parser(argc_, argv_)
    41	                .options(opt_desc_)
    42	                .positional(pos_opt_desc_)
    43	                .run(),
    44	            opt_val_);
    45	  po::notify(opt_val_);
    46	  return true;
    47	}
