    49	std::string Cat::GetDescription() const {
    50	  std::stringstream desc;
    51	  desc << "Usage: hdfs_cat [OPTION] FILE" << std::endl
    52	       << std::endl
    53	       << "Concatenate FILE to standard output." << std::endl
    54	       << std::endl
    55	       << "  -h  display this help and exit" << std::endl
    56	       << std::endl
    57	       << "Examples:" << std::endl
    58	       << "hdfs_cat hdfs://localhost.localdomain:8020/dir/file" << std::endl
    59	       << "hdfs_cat /dir/file" << std::endl;
    60	  return desc.str();
    61	}
