    63	bool Cat::Do() {
    64	  if (!Initialize()) {
    65	    std::cerr << "Unable to initialize HDFS cat tool" << std::endl;
    66	    return false;
    67	  }
    68	
    69	  if (!ValidateConstraints()) {
    70	    std::cout << GetDescription();
    71	    return false;
    72	  }
    73	
    74	  if (opt_val_.count("help") > 0) {
    75	    return HandleHelp();
    76	  }
    77	
    78	  if (opt_val_.count("path") > 0) {
    79	    const auto path = opt_val_["path"].as<std::string>();
    80	    return HandlePath(path);
    81	  }
    82	
    83	  return true;
    84	}
    85	
    86	bool Cat::HandleHelp() const {
    87	  std::cout << GetDescription();
    88	  return true;
    89	}
