    91	bool Cat::HandlePath(const std::string &path) const {
    92	  // Building a URI object from the given uri_path
    93	  auto uri = hdfs::parse_path_or_exit(path);
    94	
    95	  const auto fs = hdfs::doConnect(uri, false);
    96	  if (fs == nullptr) {
    97	    std::cerr << "Could not connect the file system." << std::endl;
    98	    return false;
    99	  }
   100	
   101	  readFile(fs, uri.get_path(), 0, stdout, false);
   102	  return true;
   103	}
