 42	
 43	  int input;
 44	
 45	  //Using GetOpt to read in the values
 46	  opterr = 0;
 47	  while ((input = getopt(argc, argv, "h")) != -1) {
 48	    switch (input)
 49	    {
 50	    case 'h':
 51	      usage();
 52	      exit(EXIT_SUCCESS);
 53	    case '?':
